// One item per export file in the drop, the taxonomy before the PIM (a product's category
// should exist first), each with the facts its source states in exports.json.
// The export files themselves are not read or changed here.
const facts = $input.first().json;
const drop = $('An export has landed').first().json['Which export?'];
return ['taxonomy', 'pim']
  .filter((source) => facts[source])
  .map((source) => ({ json: { drop, source, ...facts[source] } }));
